using System;
using System.IO;
using Newtonsoft.Json.Linq;

public class CPHInline
{
    public bool Execute()
    {
        string userId = args["userId"].ToString();
        string userName = args["userName"].ToString();
        string tier = args["tier"].ToString();

        // Determine egg reward based on tier
        int eggReward = 500; // Default Tier 1
        if (tier == "2000" || tier == "Tier 2") {
            eggReward = 1000;
        } else if (tier == "3000" || tier == "Tier 3") {
            eggReward = 2000;
        }

        // Load user data
        string dataPath = @"C:\StreamerBot\UserData\eggs.json";

        JObject data;
        if (File.Exists(dataPath)) {
            string jsonData = File.ReadAllText(dataPath);
            data = JObject.Parse(jsonData);
        } else {
            data = new JObject();
            data["users"] = new JObject();
        }

        // Initialize user if needed
        if (data["users"] == null) data["users"] = new JObject();
        if (data["users"][userId] == null) {
            data["users"][userId] = new JObject();
            data["users"][userId]["eggs"] = 0;
            data["users"][userId]["d20Tokens"] = 0;
            data["users"][userId]["rrTokens"] = 0;
        }

        // Award eggs
        int currentEggs = (int)(data["users"][userId]["eggs"] ?? 0);
        data["users"][userId]["eggs"] = currentEggs + eggReward;

        File.WriteAllText(dataPath, data.ToString());

        CPH.SendMessage($"🥚 @{userName} earned {eggReward} eggs for subscribing! Welcome to the nest! Total: {currentEggs + eggReward} eggs.");

        return true;
    }
}
